package cli

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"testing"
)

// casesDir holds one directory per scenario: case.json (the steps and the
// prune list), the input files, and want/, the reference sync_settings.py's
// result for every step, regenerated by ../settings/testdata/oracle.py.
// Each case lists the Python tests it ports in "ports"; the rest cover
// paths those tests did not.
const casesDir = "../settings/testdata/cases"

// settingsCase is a case.json.
type settingsCase struct {
	Ports          []string        `json:"ports"`
	Steps          []string        `json:"steps"`
	Prune          json.RawMessage `json:"prune"`
	LiveLink       string          `json:"live_link"`
	StderrContains []string        `json:"stderr_contains"`
	StderrExcludes []string        `json:"stderr_excludes"`
	// Deviation says why agent-sync deliberately differs from the
	// reference. A want file with a ".deviation" suffix then holds
	// agent-sync's expected value and wins over the reference's.
	Deviation string `json:"deviation"`
}

// TestSettingsMatchesReference runs every case through the CLI, step by
// step in one temp HOME, and compares each step's stdout, exit code, live
// file bytes and live file kind with the reference's.
func TestSettingsMatchesReference(t *testing.T) {
	dirs, err := filepath.Glob(filepath.Join(casesDir, "*"))
	if err != nil || len(dirs) == 0 {
		t.Fatalf("no cases under %s: %v", casesDir, err)
	}
	for _, dir := range dirs {
		t.Run(filepath.Base(dir), func(t *testing.T) { runSettingsCase(t, dir) })
	}
}

func runSettingsCase(t *testing.T, dir string) {
	var c settingsCase
	if err := json.Unmarshal(readFile(t, filepath.Join(dir, "case.json")), &c); err != nil {
		t.Fatal(err)
	}
	home := setupHome(t, dir, c.LiveLink)
	config := filepath.Join(home, "agent-sync.yaml")
	writeFile(t, config, fmt.Sprintf("settings:\n  template: %s\n  prune: %s\n",
		filepath.Join(home, "template.json"), c.Prune))

	for i, mode := range c.Steps {
		step := fmt.Sprintf("%d-%s", i+1, mode)
		var stdout, stderr bytes.Buffer
		code := Main([]string{"--config", config, "settings", mode}, &stdout, &stderr)
		kind, live := liveState(t, home)
		got := map[string]string{
			"stdout": strings.ReplaceAll(stdout.String(), home, "{HOME}"),
			"result": fmt.Sprintf("exit: %d\nlive: %s\n", code, kind),
			"live":   live,
		}
		for _, field := range []string{"stdout", "result", "live"} {
			want, ok := wantFile(t, dir, step, field)
			if !ok && field == "live" {
				want = ""
			}
			if got[field] != want {
				t.Errorf("step %s %s:\n got %q\nwant %q", step, field, got[field], want)
			}
		}
		for _, s := range c.StderrContains {
			if !strings.Contains(stderr.String(), s) {
				t.Errorf("step %s stderr = %q, want it to contain %q", step, stderr.String(), s)
			}
		}
		for _, s := range c.StderrExcludes {
			if strings.Contains(stderr.String(), s) {
				t.Errorf("step %s stderr = %q, want it free of %q", step, stderr.String(), s)
			}
		}
		if c.LiveLink == "dangling" {
			if _, err := os.Lstat(filepath.Join(home, liveTarget)); !os.IsNotExist(err) {
				t.Errorf("step %s created the dangling link's target: %v", step, err)
			}
		}
	}
}

// wantFile returns want/<step>.<field>, or its .deviation override.
func wantFile(t *testing.T, dir, step, field string) (string, bool) {
	t.Helper()
	base := filepath.Join(dir, "want", step+"."+field)
	for _, path := range []string{base + ".deviation", base} {
		data, err := os.ReadFile(path)
		if err == nil {
			return string(data), true
		}
		if !os.IsNotExist(err) {
			t.Fatal(err)
		}
	}
	return "", false
}

// liveTarget is where a linked live file points, relative to HOME.
const liveTarget = "live-target.json"

// setupHome lays a case out the way the reference's tests did: the template
// beside .claude/, the live file and overlay inside it, the live file as a
// relative symlink or a hard link when the case asks for one, or as a
// dangling symlink to a target that does not exist. testdata/oracle.py
// lays cases out the same way; change both together.
func setupHome(t *testing.T, dir, liveLink string) string {
	t.Helper()
	home, err := filepath.EvalSymlinks(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	t.Setenv("HOME", home)
	t.Setenv("CLAUDE_CONFIG_DIR", "")
	t.Setenv("XDG_CONFIG_HOME", "")
	claude := filepath.Join(home, ".claude")
	if err := os.Mkdir(claude, 0o755); err != nil {
		t.Fatal(err)
	}
	copyIfPresent(t, filepath.Join(dir, "template.json"), filepath.Join(home, "template.json"))
	copyIfPresent(t, filepath.Join(dir, "overlay.json"),
		filepath.Join(claude, "settings.local.json"))
	live := filepath.Join(claude, "settings.json")
	switch liveLink {
	case "symlink", "hardlink":
		target := filepath.Join(home, liveTarget)
		if !copyIfPresent(t, filepath.Join(dir, "live.json"), target) {
			t.Fatal("a linked live file needs live.json")
		}
		link := os.Link
		if liveLink == "symlink" {
			target, link = "../"+liveTarget, os.Symlink
		}
		if err := link(target, live); err != nil {
			t.Fatal(err)
		}
	case "dangling":
		if err := os.Symlink("../"+liveTarget, live); err != nil {
			t.Fatal(err)
		}
	default:
		copyIfPresent(t, filepath.Join(dir, "live.json"), live)
	}
	return home
}

// liveState returns what the live path is (file, symlink, hardlink or
// absent) and its content.
func liveState(t *testing.T, home string) (string, string) {
	t.Helper()
	live := filepath.Join(home, ".claude", "settings.json")
	info, err := os.Lstat(live)
	if os.IsNotExist(err) {
		return "absent", ""
	}
	if err != nil {
		t.Fatal(err)
	}
	kind := "file"
	if info.Mode()&os.ModeSymlink != 0 {
		kind = "symlink"
	} else if hardLinked(info) {
		kind = "hardlink"
	}
	data, err := os.ReadFile(live)
	if os.IsNotExist(err) {
		return kind, "" // a dangling link
	}
	if err != nil {
		t.Fatal(err)
	}
	return kind, string(data)
}

func hardLinked(info os.FileInfo) bool {
	st, ok := info.Sys().(*syscall.Stat_t)
	return ok && st.Nlink > 1
}

func copyIfPresent(t *testing.T, src, dst string) bool {
	t.Helper()
	data, err := os.ReadFile(src)
	if os.IsNotExist(err) {
		return false
	}
	if err != nil {
		t.Fatal(err)
	}
	writeFile(t, dst, string(data))
	return true
}

func readFile(t *testing.T, path string) []byte {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func writeFile(t *testing.T, path, data string) {
	t.Helper()
	if err := os.WriteFile(path, []byte(data), 0o644); err != nil {
		t.Fatal(err)
	}
}
